import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as s,o as e,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Google Antigravity","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/gemini/antigravity.md","filePath":"zh/products/ai-coding/gemini/antigravity.md","lastUpdated":1787048027000}'),n={name:"zh/products/ai-coding/gemini/antigravity.md"};function o(l,t,r,d,p,h){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="google-antigravity" tabindex="-1">Google Antigravity <a class="header-anchor" href="#google-antigravity" aria-label="Permalink to &quot;Google Antigravity&quot;">​</a></h1><blockquote><p>Google 的 agent-first 开发平台。它不是&quot;装了 AI 的编辑器&quot;——交互单位是<strong>一个任务</strong>，而不是一次按键。</p><p><strong>2026-06-18 起</strong>，个人 / Google AI Pro / Ultra 的日常入口是这里（含 CLI 表面），不再是 Gemini CLI 的「Login with Google」。<a href="https://developers.googleblog.com/an-important-update-transitioning-gemini-cli-to-antigravity-cli" target="_blank" rel="noreferrer">过渡公告</a>。</p></blockquote><h2 id="核心定位" tabindex="-1">核心定位 <a class="header-anchor" href="#核心定位" aria-label="Permalink to &quot;核心定位&quot;">​</a></h2><p>Antigravity 假设 AI 能自主规划、调用工具、执行多步任务。这个前提改变了你该给它什么输入：补全式工具需要光标位置，Antigravity 需要目标、约束和验收标准。</p><p>它的能力边界由三件事决定：</p><table tabindex="0"><thead><tr><th>你提供什么</th><th>载体</th><th>作用</th></tr></thead><tbody><tr><td>长期不变量</td><td><a href="#规则-rules">规则</a></td><td>&quot;这个项目必须这样做&quot;</td></tr><tr><td>可复用流程</td><td><a href="#技能-skills">技能</a> 与 <a href="#工作流-workflows">工作流</a></td><td>&quot;遇到这类活儿按这个套路&quot;</td></tr><tr><td>外部世界</td><td>MCP</td><td>让它能查 GitHub、驱动浏览器</td></tr></tbody></table><h2 id="多表面-surfaces" tabindex="-1">多表面（Surfaces） <a class="header-anchor" href="#多表面-surfaces" aria-label="Permalink to &quot;多表面（Surfaces）&quot;">​</a></h2><p>官方把 Antigravity 描述为构建在<strong>同一套智能体 harness</strong> 之上的多个表面：</p><table tabindex="0"><thead><tr><th>表面</th><th>形态</th><th>适合</th></tr></thead><tbody><tr><td>桌面应用</td><td>图形界面</td><td>交互式探索，边看边验证</td></tr><tr><td>CLI</td><td>终端 UI</td><td>接进已有脚本与终端工作流</td></tr><tr><td>SDK</td><td>Python</td><td>把智能体嵌进自己的自动化</td></tr><tr><td>IDE 集成</td><td>编辑器内</td><td>不离开现有编辑器</td></tr></tbody></table><p><strong>这是最实用的一条认知</strong>：因为共享同一套 harness，规则与技能是<strong>跨表面生效</strong>的。你不需要为桌面端和 CLI 各配一份，也不用重新学一套心智模型——按当下的工作方式挑入口就行。</p><p>驱动模型方面，官方模型文档标注 Gemini 3.5 Flash 驱动 Antigravity 的全部本地智能体；托管形态另有 <code>antigravity-preview-05-2026</code>，官方描述为在隔离的 Linux 沙盒里自主规划、执行代码、管理文件、浏览网页的通用托管智能体。</p><h2 id="规则-rules" tabindex="-1">规则（Rules） <a class="header-anchor" href="#规则-rules" aria-label="Permalink to &quot;规则（Rules）&quot;">​</a></h2><p>规则是长期生效的行为约束，分两级：</p><table tabindex="0"><thead><tr><th>级别</th><th>位置</th><th>生效范围</th></tr></thead><tbody><tr><td>全局</td><td><code>~/.gemini/GEMINI.md</code></td><td>全部工作区</td></tr><tr><td>工作区</td><td><code>.agents/rules</code> 目录</td><td>随仓库走，可提交</td></tr></tbody></table><p><strong>官方明确每个规则文件上限 12,000 字符。</strong> 到了上限应该拆分文件并用 <code>@filename</code> 交叉引用，而不是靠压缩措辞硬塞。</p><h3 id="四种激活模式" tabindex="-1">四种激活模式 <a class="header-anchor" href="#四种激活模式" aria-label="Permalink to &quot;四种激活模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>何时加载</th><th>适合</th></tr></thead><tbody><tr><td>Manual</td><td>你手动引用时</td><td>偶尔才需要的约定</td></tr><tr><td>Always On</td><td>每次都加载</td><td>真正的全局铁律</td></tr><tr><td>Model Decision</td><td>模型判断需要时</td><td>场景性的建议</td></tr><tr><td>Glob</td><td>匹配到指定文件模式时</td><td>技术栈相关的规范</td></tr></tbody></table><p><strong>优先用 Glob。</strong> &quot;React 组件规范&quot;只在匹配 <code>src/**/*.tsx</code> 时加载，比 Always On 一直占着上下文划算得多。Always On 应该留给数量极少的真正不变量。</p><h3 id="规则里该写什么" tabindex="-1">规则里该写什么 <a class="header-anchor" href="#规则里该写什么" aria-label="Permalink to &quot;规则里该写什么&quot;">​</a></h3><p>只写<strong>智能体容易做错的</strong>那几条：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 项目约束</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 包管理器只用 pnpm，禁止出现 npm install / yarn add</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 所有新增组件必须有显式的 Props 类型，不允许 any</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> src/legacy/ 目录只读，任何改动需要先问</span></span></code></pre></div><p>不要把整份编码规范粘进去。它本来就会写分号。</p><blockquote><p>⚠️ 规则文件<strong>不是</strong>项目根目录的 <code>agents.md</code>。这是历史版本文档里的错误写法，路径是 <code>~/.gemini/GEMINI.md</code>（全局）与 <code>.agents/rules</code> 目录（工作区）。</p></blockquote><h2 id="技能-skills" tabindex="-1">技能（Skills） <a class="header-anchor" href="#技能-skills" aria-label="Permalink to &quot;技能（Skills）&quot;">​</a></h2><p>技能是<strong>一个目录</strong>，里面放一个 <code>SKILL.md</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.agents/skills/release-flow/          # 随仓库走</span></span>
<span class="line"><span>└── SKILL.md</span></span>
<span class="line"><span></span></span>
<span class="line"><span>~/.gemini/config/skills/release-flow/ # 全局</span></span>
<span class="line"><span>└── SKILL.md</span></span></code></pre></div><p>frontmatter 里 <code>description</code> 必填，<code>name</code> 可选：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">当需要给这个项目发版时使用，覆盖版本号、changelog、tag 的完整流程</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 发版流程</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 确认 main 分支 CI 全绿</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 更新 CHANGELOG.md</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ...</span></span></code></pre></div><p><strong><code>description</code> 决定这个技能会不会被用上</strong>，所以它要写成触发条件（&quot;当需要发版时…&quot;），不要写成标题（&quot;发版流程&quot;）。模型是拿它来判断当前任务是否匹配的。</p><p><strong>因为技能是目录</strong>，你可以把脚本、模板、示例数据一起放进去，让 <code>SKILL.md</code> 引用它们——这是它和单个提示词文件最大的区别。</p><blockquote><p>⚠️ <code>.agents/skills/xxx.md</code> 这种扁平单文件写法不会被识别为技能。<code>.agent/skills</code>（单数）仅为向后兼容保留，新建请用 <code>.agents/skills</code>。</p></blockquote><h2 id="工作流-workflows" tabindex="-1">工作流（Workflows） <a class="header-anchor" href="#工作流-workflows" aria-label="Permalink to &quot;工作流（Workflows）&quot;">​</a></h2><p>工作流用 <code>/&lt;workflow-name&gt;</code> 显式调用。</p><p><strong>和技能怎么分</strong>：触发权归属不同。</p><ul><li>技能：模型看 <code>description</code> 自己决定要不要用</li><li>工作流：你决定什么时候跑</li></ul><p>想让它自动匹配就写技能，想自己掐时间点就写工作流。上线前检查、生成周报这类&quot;必须由人发起&quot;的流程属于后者。</p><h2 id="子智能体与构件" tabindex="-1">子智能体与构件 <a class="header-anchor" href="#子智能体与构件" aria-label="Permalink to &quot;子智能体与构件&quot;">​</a></h2><p>这两个机制是 Antigravity 处理大任务的关键，也是它和&quot;一个更聪明的补全工具&quot;的分界线。</p><p><strong>异步子智能体（Asynchronous Subagents）</strong>：主智能体派出下级智能体并行干活。价值在于上下文经济——让子智能体各自读一个模块、各自返回结论，主智能体只消费结论而不消费原始文件，同样的窗口能处理大得多的任务。</p><p><strong>构件（Artifacts）</strong>：智能体产出的可审查中间产物，比如计划、任务清单、验证记录。它是自主性的配套刹车：智能体越自主，&quot;它到底打算干什么&quot;就越不透明，构件把黑箱中间态变成你可以读、可以否决的东西。</p><h2 id="典型工作流-跨模块重构" tabindex="-1">典型工作流：跨模块重构 <a class="header-anchor" href="#典型工作流-跨模块重构" aria-label="Permalink to &quot;典型工作流：跨模块重构&quot;">​</a></h2><p>这是 Antigravity 相对其他工具优势最明显的场景，因为上面两个机制正好对上它的风险。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 描述目标与验收标准，让它先产出计划构件</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>2. 读计划，否决方向不对的部分     ← 关键的人工卡点</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>3. 放它执行（子智能体可并行读多个模块）</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>4. 用它的验证记录判断该信多少，再自己复核关键改动</span></span></code></pre></div><p><strong>开跑前确认工作区是干净的。</strong> 并发意味着改动来自多个方向，事后你分不清哪处是谁改的。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>规则明明写了它却不遵守</strong>：先确认激活模式。Manual 模式的规则不会自动加载；Glob 模式要确认当前改的文件真的匹配上了模式。</p><p><strong>技能没被触发</strong>：<code>description</code> 写成了标题而不是触发条件。改成&quot;当…时使用&quot;的句式。</p><p><strong>上下文很快就满</strong>：Always On 的规则太多。把技术栈相关的挪到 Glob。</p><h2 id="与其他产品怎么选" tabindex="-1">与其他产品怎么选 <a class="header-anchor" href="#与其他产品怎么选" aria-label="Permalink to &quot;与其他产品怎么选&quot;">​</a></h2><p>Antigravity（本地、你实时对话）vs Code Assist（IDE 内、编辑器触发）vs Jules（云端、异步产出 PR）的完整对比表见 <a href="./gemini-cheatsheet.html#antigravity-vs-code-assist-vs-jules">速查表</a>，本页不重复。</p><p>一句话版本：<strong>要边看边验证的本地大改动用 Antigravity，丢出去等 PR 用 <a href="./jules.html">Jules</a>，编辑器里的小范围改动用 <a href="./code-assist.html">Code Assist</a>。</strong></p><h2 id="官方资源" tabindex="-1">官方资源 <a class="header-anchor" href="#官方资源" aria-label="Permalink to &quot;官方资源&quot;">​</a></h2><ul><li><a href="https://antigravity.google/docs/home" target="_blank" rel="noreferrer">Antigravity 文档首页</a></li><li><a href="https://antigravity.google/docs/rules-workflows" target="_blank" rel="noreferrer">规则与工作流</a></li><li><a href="https://antigravity.google/docs/skills" target="_blank" rel="noreferrer">技能</a></li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./gemini-cheatsheet.html">速查表</a> — 规则/技能路径速查、跨产品决策表</li><li><a href="./gemini-glossary.html">术语表</a> — Surface、Rules、Skill、Subagent、Artifact 的概念定义</li><li><a href="./gemini-cookbook.html#_11-跨模块重构-需要边看边验证">Cookbook</a> — 跨模块重构配方</li></ul>`,55)])])}const m=a(n,[["render",o]]);export{b as __pageData,m as default};
